/**
 * This view maintains all the below states...
 * 1. Loading state
 * 2. Empty state
 * 3. List state
 * 4. Error state
 * 
 **/
csui.define('smart/controls/list/list.state/list.state.view',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'smart/behaviors/collection.state/collection.state.view',
  'smart/themes/theming',
  'smart/themes/jato.icons/smart.jato.illustrations',
  'i18n!smart/controls/list/list.state/impl/nls/lang',
  'hbs!smart/controls/list/list.state/impl/list.state',
  'css!smart/controls/list/list.state/impl/list.state'
], function (_, $, CollectionStateView, theming, jatoIllustrations, lang, template) {

  const isJato = () => theming.isJATOTheme();

  var EmptyListView = CollectionStateView.extend({

    constructor: function EmptyListView(options = {}) {
      CollectionStateView.prototype.constructor.apply(this, arguments);
    },

    className: 'cs-emptylist-container ' + CollectionStateView.prototype.className,

    template,

    serializeData: function () {
      let data = CollectionStateView.prototype.serializeData.apply(this, arguments);
      let emptyListPlaceholderIcon = this.options.emptyJatoIllustration ?? jatoIllustrations.illustrationsGenericListSmall;
      const defaultText = this.options?.text || lang.emptyViewDefaultText;
      let text = data ? (data.state === "loading" ? "" : (data.message || defaultText)) : defaultText;
      let messages = {
        isJATOTheme: isJato(),
        text,
        emptyListPlaceholderIcon
      };
      return messages;
    }

  });

  return EmptyListView;

});
