csui.define('smart/controls/app.header/search/slices/slices.view',[
  "module",
  "nuc/lib/underscore",
  "nuc/lib/jquery",
  "nuc/lib/marionette",
  "smart/controls/app.header/search/slices/slice.item.view",
  "i18n!smart/controls/app.header/search/impl/nls/lang",
], function (module, _, $, Marionette, SliceItemView, lang) {
  let SearchBoxsliceCollView = Marionette.CollectionView.extend({
    tagName: "otc-menugroup",

    className: "sliceContainer",

    childView: SliceItemView,

    childViewOptions: function () {
      return {
        leadingView: this.options.leadingView,
      };
    },

    attributes: function () {
      let attr = {
        name: lang.searchWithinText,
        allowdeselection: true
      };
      return attr;
    },

    constructor: function SearchBoxsliceCollView(options = {}) {
      Marionette.CollectionView.apply(this, arguments);
      this.listenTo(this, "reorder:collection", this._reorder);
      this._reorder();
    },

    _reorder: function () {
      let selectedSlice = this?.options?.leadingView?.otcData?.selectedSlice ?? '',
        original_index = this.collection.findIndex({ id: selectedSlice }),
        new_index = 0;

      if (new_index !== original_index) {
        // Get the model being moved
        var temp = this.collection.at(original_index);
        // Remove it
        this.collection.remove(temp);
        // Add it back in at the new index
        this.collection.add(temp, { at: new_index });
      } else {
        // If nothing is being changed, do-nothing
      }
      return this;
    },
  });

  return SearchBoxsliceCollView;
});
