csui.define('smart/controls/facet.panel/impl/facet/facet.empty/facet.empty.view',[
  "nuc/lib/jquery",
  "nuc/lib/underscore",
  "nuc/lib/marionette",
  'smart/themes/theming',
  'smart/themes/jato.icons/smart.jato.illustrations',
  "i18n!smart/controls/facet.panel/impl/facet/facet.empty/impl/nls/lang",
  "hbs!smart/controls/facet.panel/impl/facet/facet.empty/impl/facet.empty",
  "css!smart/controls/facet.panel/impl/facet/facet.empty/impl/facet.empty",
], function ($, _, Marionette, theming, jatoIllustrations, lang, template) {

  const isJato = () => theming.isJATOTheme();

  var FacetEmptyView = Marionette.ItemView.extend({
    template,
    className: "smart-facet-empty",

    constructor: function FacetEmptyView(options = {}) {
      Marionette.ItemView.prototype.constructor.apply(this, arguments);
    },
    templateHelpers: function () {
      let emptyMessage = lang.searchNoresults;
      let emptyFacetsPlaceholderJATOIcon = jatoIllustrations.illustrationsNoFiles;
      let  isJATOTheme = isJato();
      return {
        isJATOTheme,
        emptyFacetsPlaceholderJATOIcon,
        emptyMessage,
      };
    },
  });

  return FacetEmptyView;
});
