csui.define('smart/controls/facet.panel/impl/facet/facet.view',[
  'nuc/lib/underscore', 'module',
  'nuc/lib/jquery',
  'nuc/lib/marionette',
  'smart/controls/facet.panel/impl/facet/facet.item.view',
  'smart/controls/facet.panel/impl/facet/facet.empty/facet.empty.view'
], function (_, module, $, Marionette, FacetItemView, FacetEmptyView) {

  var config = module.config();
  _.defaults(config, {
    displayCount: 'Always'
  });

  var FacetView = Marionette.CollectionView.extend({

    childView: FacetItemView,
    emptyView: FacetEmptyView,

    childViewContainer: '.cs-filter-group',

    childViewOptions: function () {
      //Checkboxes will be enabled by default. To disable checkboxes set 'select_multiple' as false.
      return {
        enableCheckBoxes: this.model.get('select_multiple') !== undefined ?
                          this.model.get('select_multiple') : true,
        displayCountProps: this.displayCountProps,
        maxCount: this.maxCount,
        context: this.options.context,
        showButtonsInEachFacet: this.showButtonsInEachFacet,
        facetCardView: this.options.facetCardView
      };

    },

    constructor: function FacetView(options = {}) {
      options.data || (options.data = {});
      this.showButtonsInEachFacet = options.showButtonsInEachFacet;
      this.displayCountProps = options.displayCountProps,
      Marionette.CollectionView.prototype.constructor.apply(this, arguments);
      this.maxCount = this.options.maxCount;
    },

    filter : function(view, index, children) {
      let value = this.maxCount ? index < this.maxCount : true;
      return value;
    },

  });

  return FacetView;
});
  